#include <stdlib.h>
#include <string.h>
#include <omp.h>
#if defined(__x86_64__) || defined(__i386__)
#include <immintrin.h>
#define HAVE_X86 1
#endif

typedef void (*kern_t)(long kc, const float *a, const float *b,
                       float *c, long ldc, int first);

/* ---------------- generic kernel (6x16) ---------------- */
static void kern_gen(long kc, const float *a, const float *b,
                     float *c, long ldc, int first)
{
    float acc[6][16];
    memset(acc, 0, sizeof(acc));
    for (long k = 0; k < kc; k++) {
        const float *bk = b + k * 16;
        const float *ak = a + k * 6;
        for (int r = 0; r < 6; r++) {
            float av = ak[r];
            for (int j = 0; j < 16; j++) acc[r][j] += av * bk[j];
        }
    }
    for (int r = 0; r < 6; r++) {
        float *cr = c + r * ldc;
        if (first) for (int j = 0; j < 16; j++) cr[j] = acc[r][j];
        else       for (int j = 0; j < 16; j++) cr[j] += acc[r][j];
    }
}

#ifdef HAVE_X86
/* ---------------- AVX2 kernel (6x16) ---------------- */
#define Z2(r) __m256 c##r##_0 = _mm256_setzero_ps(), c##r##_1 = _mm256_setzero_ps();
#define R2(r) { __m256 av = _mm256_broadcast_ss(a + r);            \
    c##r##_0 = _mm256_fmadd_ps(av, b0, c##r##_0);                  \
    c##r##_1 = _mm256_fmadd_ps(av, b1, c##r##_1); }
#define S2(r) { float *cr = c + (r) * ldc;                          \
    if (first) { _mm256_storeu_ps(cr, c##r##_0);                   \
                 _mm256_storeu_ps(cr + 8, c##r##_1); }             \
    else { _mm256_storeu_ps(cr, _mm256_add_ps(_mm256_loadu_ps(cr), c##r##_0)); \
           _mm256_storeu_ps(cr + 8, _mm256_add_ps(_mm256_loadu_ps(cr + 8), c##r##_1)); } }

__attribute__((target("avx2,fma")))
static void kern_avx2(long kc, const float *a, const float *b,
                      float *c, long ldc, int first)
{
    Z2(0) Z2(1) Z2(2) Z2(3) Z2(4) Z2(5)
#pragma GCC unroll 4
    for (long k = 0; k < kc; k++) {
        __m256 b0 = _mm256_load_ps(b);
        __m256 b1 = _mm256_load_ps(b + 8);
        R2(0) R2(1) R2(2) R2(3) R2(4) R2(5)
        a += 6; b += 16;
    }
    S2(0) S2(1) S2(2) S2(3) S2(4) S2(5)
}

/* ---------------- AVX-512 kernel (12x32) ---------------- */
#define Z5(r) __m512 c##r##_0 = _mm512_setzero_ps(), c##r##_1 = _mm512_setzero_ps();
#define R5(r) { __m512 av = _mm512_set1_ps(a[r]);                   \
    c##r##_0 = _mm512_fmadd_ps(av, b0, c##r##_0);                  \
    c##r##_1 = _mm512_fmadd_ps(av, b1, c##r##_1); }
#define S5(r) { float *cr = c + (r) * ldc;                          \
    if (first) { _mm512_storeu_ps(cr, c##r##_0);                   \
                 _mm512_storeu_ps(cr + 16, c##r##_1); }            \
    else { _mm512_storeu_ps(cr, _mm512_add_ps(_mm512_loadu_ps(cr), c##r##_0)); \
           _mm512_storeu_ps(cr + 16, _mm512_add_ps(_mm512_loadu_ps(cr + 16), c##r##_1)); } }

__attribute__((target("avx512f,avx2,fma")))
static void kern_avx512(long kc, const float *a, const float *b,
                        float *c, long ldc, int first)
{
    Z5(0) Z5(1) Z5(2) Z5(3) Z5(4) Z5(5) Z5(6) Z5(7) Z5(8) Z5(9) Z5(10) Z5(11)
#pragma GCC unroll 2
    for (long k = 0; k < kc; k++) {
        __m512 b0 = _mm512_load_ps(b);
        __m512 b1 = _mm512_load_ps(b + 16);
        R5(0) R5(1) R5(2) R5(3) R5(4) R5(5)
        R5(6) R5(7) R5(8) R5(9) R5(10) R5(11)
        a += 12; b += 32;
    }
    S5(0) S5(1) S5(2) S5(3) S5(4) S5(5)
    S5(6) S5(7) S5(8) S5(9) S5(10) S5(11)
}
#endif

/* ---------------- buffers ---------------- */
static float *g_ap = NULL, *g_bp = NULL;
static size_t g_acap = 0, g_bcap = 0;

static float *grow(float **p, size_t *cap, size_t need)
{
    if (need > *cap) {
        free(*p);
        size_t bytes = (need * sizeof(float) + 63) & ~(size_t)63;
        *p = (float *)aligned_alloc(64, bytes);
        *cap = need;
    }
    return *p;
}

#define KC 256

void matmul(const float *A, const float *B, float *C, int n_)
{
    long n = n_;
    if (n <= 48) {
        for (long i = 0; i < n; i++) {
            float *ci = C + i * n;
            for (long j = 0; j < n; j++) ci[j] = 0.0f;
            for (long k = 0; k < n; k++) {
                float a = A[i * n + k];
                const float *bk = B + k * n;
                for (long j = 0; j < n; j++) ci[j] += a * bk[j];
            }
        }
        return;
    }

    kern_t kern = kern_gen;
    long MR = 6, NR = 16, MB = 12, NB = 8;
#ifdef HAVE_X86
    __builtin_cpu_init();
    if (__builtin_cpu_supports("avx512f")) {
        kern = kern_avx512; MR = 12; NR = 32; MB = 8; NB = 4;
    } else if (__builtin_cpu_supports("avx2") && __builtin_cpu_supports("fma")) {
        kern = kern_avx2; MR = 6; NR = 16; MB = 12; NB = 8;
    }
#endif

    long mp = (n + MR - 1) / MR, np = (n + NR - 1) / NR;
    float *Ap = grow(&g_ap, &g_acap, (size_t)(mp * MR) * KC);
    float *Bp = grow(&g_bp, &g_bcap, (size_t)(np * NR) * KC);
    long tiM = (mp + MB - 1) / MB, tiN = (np + NB - 1) / NB;
    long ntask = tiM * tiN;

#pragma omp parallel
    {
        for (long pc = 0; pc < n; pc += KC) {
            long kc = n - pc < KC ? n - pc : KC;
            int first = (pc == 0);

#pragma omp for schedule(static) nowait
            for (long jp = 0; jp < np; jp++) {
                long j0 = jp * NR;
                float *dst = Bp + jp * NR * kc;
                if (j0 + NR <= n) {
                    for (long k = 0; k < kc; k++)
                        memcpy(dst + k * NR, B + (pc + k) * n + j0, NR * sizeof(float));
                } else {
                    long nr = n - j0;
                    for (long k = 0; k < kc; k++) {
                        const float *src = B + (pc + k) * n + j0;
                        long j = 0;
                        for (; j < nr; j++) dst[k * NR + j] = src[j];
                        for (; j < NR; j++) dst[k * NR + j] = 0.0f;
                    }
                }
            }

#pragma omp for schedule(static)
            for (long ip = 0; ip < mp; ip++) {
                long i0 = ip * MR;
                float *dst = Ap + ip * MR * kc;
                for (long r = 0; r < MR; r++) {
                    if (i0 + r < n) {
                        const float *src = A + (i0 + r) * n + pc;
                        for (long k = 0; k < kc; k++) dst[k * MR + r] = src[k];
                    } else {
                        for (long k = 0; k < kc; k++) dst[k * MR + r] = 0.0f;
                    }
                }
            }

#pragma omp for schedule(dynamic, 1)
            for (long t = 0; t < ntask; t++) {
                long ib = t / tiN, jb = t % tiN;
                long ipe = (ib + 1) * MB < mp ? (ib + 1) * MB : mp;
                long jpe = (jb + 1) * NB < np ? (jb + 1) * NB : np;
                for (long jp = jb * NB; jp < jpe; jp++) {
                    const float *bp = Bp + jp * NR * kc;
                    long j0 = jp * NR;
                    for (long ip = ib * MB; ip < ipe; ip++) {
                        const float *ap = Ap + ip * MR * kc;
                        long i0 = ip * MR;
                        if (i0 + MR <= n && j0 + NR <= n) {
                            kern(kc, ap, bp, C + i0 * n + j0, n, first);
                        } else {
                            float tmp[12 * 32] __attribute__((aligned(64)));
                            kern(kc, ap, bp, tmp, NR, 1);
                            long mr = n - i0 < MR ? n - i0 : MR;
                            long nr = n - j0 < NR ? n - j0 : NR;
                            for (long r = 0; r < mr; r++) {
                                float *cr = C + (i0 + r) * n + j0;
                                const float *tr = tmp + r * NR;
                                if (first) for (long j = 0; j < nr; j++) cr[j] = tr[j];
                                else       for (long j = 0; j < nr; j++) cr[j] += tr[j];
                            }
                        }
                    }
                }
            }
        }
    }
}
